import{b as a,O as i,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const r=JSON.parse('{"title":"环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"automation/pytest/intro/setup/index.md","filePath":"自动化测试/2.pytest+requests/1.入门篇/02.环境搭建.md","lastUpdated":1786983642000}'),n={name:"automation/pytest/intro/setup/index.md"};function p(l,s,h,d,o,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="环境搭建" tabindex="-1">环境搭建 <a class="header-anchor" href="#环境搭建" aria-label="Permalink to &quot;环境搭建&quot;">​</a></h1><blockquote><p>装好 pytest 和 requests，跑通第一个测试之前的一切准备工作。这一章很短，但「虚拟环境」这一步能帮你避开 Python 新手最常见的坑。</p></blockquote><h2 id="前置-python" tabindex="-1">前置：Python <a class="header-anchor" href="#前置-python" aria-label="Permalink to &quot;前置：Python&quot;">​</a></h2><p>pytest 需要 Python 3.9+（本教程基于 Python 3.12 和 pytest 8.4.2）。先确认环境：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Python 3.12.0</span></span></code></pre></div><p>如果你的系统里 <code>python3</code> 指向的是旧版本，或者装了好几个 Python，建议先解决版本管理（pyenv 或直接装最新版），避免后面踩「装到了别的 Python 上」的坑。</p><h2 id="创建虚拟环境" tabindex="-1">创建虚拟环境 <a class="header-anchor" href="#创建虚拟环境" aria-label="Permalink to &quot;创建虚拟环境&quot;">​</a></h2><p><strong>强烈建议每个项目一个虚拟环境（venv）</strong>，而不是全局 <code>pip install</code>。原因：</p><ul><li>不同项目依赖的版本可能冲突（A 项目要 pytest 7，B 项目要 pytest 8）</li><li>全局环境被污染后很难排查</li><li>虚拟环境可以一键删除重建，坏了也不心疼</li></ul><p>在项目目录下创建并激活：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv/bin/activate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">venv\\Scripts\\activate</span></span></code></pre></div><p>激活成功后，命令行提示符前面会出现 <code>(venv)</code>，说明之后的 <code>pip install</code> 都装进这个独立环境了。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(venv) ~/cart $</span></span></code></pre></div><blockquote><p><strong>要点：以后每次写代码、跑测试前，都要先 <code>source venv/bin/activate</code>（Windows 用 <code>venv\\Scripts\\activate</code>）。忘了激活就会装错地方、跑错环境。</strong></p></blockquote><h2 id="安装-pytest-和-requests" tabindex="-1">安装 pytest 和 requests <a class="header-anchor" href="#安装-pytest-和-requests" aria-label="Permalink to &quot;安装 pytest 和 requests&quot;">​</a></h2><p>本教程的核心就两个库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests</span></span></code></pre></div><p>验证安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pytest 8.4.2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import requests; print(requests.__version__)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2.32.3</span></span></code></pre></div><p><code>pytest --version</code> 除了版本号，还会列出已安装的插件和它们的版本——后面排查「某个功能为什么没生效」时，这个输出很有用。</p><h2 id="安装常用插件-可选-进阶篇用" tabindex="-1">安装常用插件（可选，进阶篇用） <a class="header-anchor" href="#安装常用插件-可选-进阶篇用" aria-label="Permalink to &quot;安装常用插件（可选，进阶篇用）&quot;">​</a></h2><p>pytest 的能力很大一部分来自插件。这里先装几个本教程进阶篇会讲到的，现在装了不碍事：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-html</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 生成 HTML 测试报告</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-xdist</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 多进程并行执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-mock</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 更强大的 mock 支持</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest-cov</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 覆盖率统计</span></span></code></pre></div><blockquote><p><strong>要点：这 4 个是接口测试最常用的 pytest 插件，本教程进阶篇会逐一讲解用法。现在先装上，<code>pytest --version</code> 里能看到它们就算装好了。</strong></p></blockquote><h2 id="初始化项目结构" tabindex="-1">初始化项目结构 <a class="header-anchor" href="#初始化项目结构" aria-label="Permalink to &quot;初始化项目结构&quot;">​</a></h2><p>入门篇先搭一个最小结构，后面实战篇会扩展成完整框架：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cart/                          # 项目根目录</span></span>
<span class="line"><span>├── venv/                      # 虚拟环境（不提交到 git）</span></span>
<span class="line"><span>├── cart.py                    # 被测代码</span></span>
<span class="line"><span>└── test_cart.py               # 测试代码</span></span></code></pre></div><p>跑一下确认环境通了：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果一切正常，你已经准备好进入下一章写第一个测试了。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p>装环境时最容易踩的几个坑，先记下来：</p><table tabindex="0"><thead><tr><th>问题</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td><code>pytest: command not found</code></td><td>虚拟环境没激活</td><td>先 <code>source venv/bin/activate</code></td></tr><tr><td>版本装到了全局 Python</td><td>没在虚拟环境里 pip</td><td>激活后再 <code>pip install</code></td></tr><tr><td><code>pip</code> 报 SSL 证书错误</td><td>公司网络/代理</td><td>配置 pip 镜像源或代理</td></tr><tr><td>同时有 <code>python</code> 和 <code>python3</code></td><td>系统装了多个 Python</td><td>统一用 <code>python3 -m venv</code> 创建，用 <code>python3 -m pip</code> 安装</td></tr></tbody></table><p>国内网络 pip 慢的话，可以换清华镜像：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pypi.tuna.tsinghua.edu.cn/simple</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests</span></span></code></pre></div><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ul><li>pytest 需要 Python 3.9+，本教程基于 Python 3.12 + pytest 8.4.2</li><li><strong>每个项目一个虚拟环境</strong>（<code>python3 -m venv venv</code>），用之前先激活</li><li>核心库就两个：<code>pip install pytest requests</code></li><li><code>pytest --version</code> 能同时看到插件列表，是排查问题的第一手信息</li><li>进阶篇要用的 4 个插件：<code>pytest-html</code>、<code>pytest-xdist</code>、<code>pytest-mock</code>、<code>pytest-cov</code></li></ul>`,37)])])}const y=a(n,[["render",p]]);export{r as __pageData,y as default};
